"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Οποιοδήποτε δωμάτιο: πιθανότητα σχεδίου +{0}%. Ταιριάζει σε «Σφυρηλάτηση»: {1}% πιθανότητα για επιπλέον κειμήλιο στη σφυρηλάτηση.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Οποιοδήποτε δωμάτιο: βάση: Θραύσματα Ψυχής +{0} τη μέρα. Ταιριάζει σε «Μαγεία»: επιπλέον +{1} τη μέρα.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Οποιοδήποτε δωμάτιο: βάση: εφόδια +{0} τη μέρα. Ταιριάζει σε «Επιμελητεία»: το δικό αποτέλεσμα του δωματίου ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Οποιοδήποτε δωμάτιο: βάση: εφόδια +{0} τη μέρα, εμπειρία αρχηγού +{1} τη μέρα. Ταιριάζει σε «Επιμελητεία / Φύση»: το δικό αποτέλεσμα του δωματίου ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Οποιοδήποτε δωμάτιο: κόστος σφυρηλάτησης κειμηλίων -{0}%. Ταιριάζει σε «Σφυρηλάτηση / Όπλο»: σφυρηλάτηση με {1}% πιθανότητα για ποιότητα +{2}· τα όπλα κάνουν +{3}% ζημιά.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Οποιοδήποτε δωμάτιο: χρόνος κατασκευής στο μισό, επιστροφή {0}% των εφοδίων στην ολοκλήρωση. Ταιριάζει σε «Θαύμα»: η επιστροφή ανεβαίνει στο {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Οποιοδήποτε δωμάτιο: όλοι οι αμυντικοί πύργοι κάνουν +{0}% ζημιά. Ταιριάζει σε «Όπλο»: βεληνεκές +{1}, ταχύτητα επίθεσης +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Οποιοδήποτε δωμάτιο: κόστος σκαψίματος -{0}%. Ταιριάζει σε «Ειδικό»: όλες οι κατασκευές θέλουν {1} ημ. λιγότερο.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Οποιοδήποτε δωμάτιο: αρχικός πολλαπλασιαστής πόντων +{0} σε κάθε μάχη. Ταιριάζει σε «Σφυρηλάτηση»: τα σφυρηλατημένα κειμήλια έχουν πάντα ποιότητα +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Οποιοδήποτε δωμάτιο: επαναφόρτιση ικανότητας αρχηγού -{0} στάσεις. Ταιριάζει σε «Τύχη»: επιπλέον βοηθητικά αντικείμενα στην αρχή των εκστρατειών +{1} (τουλάχιστον «Επικό» αποτέλεσμα).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Οποιοδήποτε δωμάτιο: επίθεση αρχηγού +{0}%. Ταιριάζει σε «Όπλο»: ζημιά +{1}%, κάθε επίθεση εξαπολύει αλυσιδωτό κεραυνό (πηδά σε {2} εχθρούς).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Οποιοδήποτε δωμάτιο: ο αρχηγός σου ανακτά {0}% ζωής τη μέρα (χωρίς νοσοκομείο). Ταιριάζει σε «Ιατρική / Νερό»: θεραπεία νοσοκομείου +{1}%· βεληνεκές υδάτινων όπλων +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Οποιοδήποτε δωμάτιο: εμπειρία αρχηγού +{0} τη μέρα. Ταιριάζει σε «Παραγωγή»: η δική παραγωγή του δωματίου ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Οποιοδήποτε δωμάτιο: εμπειρία αρχηγού +{0} τη μέρα. Ταιριάζει σε «Εκπαίδευση»: εμπειρία αρχηγού από εκστρατείες +{1}%.",
