"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Μπροστά: «Νεκροταφείο»: η ομίχλη είναι πιο πυκνή εκεί, και οι καινούργιοι τάφοι πληθαίνουν κάθε νύχτα.",
