"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Μπροστά: «Χειρουργείο»: ο διευθυντής λέει πως η επέμβαση πέτυχε—ο ασθενής απλώς δεν ξύπνησε ακόμα.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Μπροστά: «Βυθός»: κάτω από το λιμάνι υπάρχει κι άλλη πόλη, και η πύλη της είναι ένα στόμα.",
