"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Μπροστά: «Βασίλισσα των Ξωτικών»: περιμένει τριακόσια χρόνια δίπλα στη λίμνη του φεγγαριού. Λέει πως είσαι αυτός που περίμενε.",
